/* setInterval(function(){ },3000); 3초마다 {}안에 내용을 반복 */
setInterval(function(){
$('.imgs').animate({
left: '-1000px' /* .imgs를 왼쪽으로 -1000px 애니메이션 움직임을 줌 */
}, function(){
$('.slide img'),eq(0),appendTo('.imgs');
/* $('.slide img').eq(0) eq(n) n번째에 .slide img를 */
/* appendTo('.imgs'); .imgs에 마지막으로 이동 */
$('.imgs').css({
left: 0 /* .imgs를 left:0으로 이동 */
});
});
},3000);

